trigger OpportunityPriorityFlag on Opportunity (before insert, before update) {
    for (Opportunity opp : Trigger.new) {
        if (opp.Amount != null && opp.Amount > 100000) {
            opp.Priority_Flag__c = true;
        } else {
            opp.Priority_Flag__c = false;
        }
    }
}

