This Apex method queries inside a for loop, which will hit governor limits at scale. Rewrite it to query once outside the loop instead.

public void flagAccounts(List<Id> accountIds) {
    for (Id accId : accountIds) {
        Account acc = [SELECT Id, Industry FROM Account WHERE Id = :accId];
        if (acc.Industry == 'Technology') {
            acc.Rating = 'Hot';
            update acc;
        }
    }
}

